python3 - <<'EOF'
p='src/pickList.ts'
s=open(p).read()
i=s.index('export function buildPickList')
s=s[:i]+'''interface ParsedOrder {
  id: string;
  line: number;
  priority: boolean;
  items: { sku: string; qty: number }[];
}

const ORDER_LINE = /^ORDER +([A-Za-z0-9-]+)( +!)?$/;
const ITEM_LINE = /^([A-Z0-9-]+) +x([1-9][0-9]*)$/;

function parseOrders(text: string): ParsedOrder[] {
  const orders: ParsedOrder[] = [];
  const seen = new Set<string>();
  // Collect every problem so the topmost one wins, even when it is only
  // detectable later (an ORDER without items).
  const errors: { line: number; description: string }[] = [];
  let current: ParsedOrder | null = null;

  text.split("\\n").forEach((raw, index) => {
    const lineNo = index + 1;
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) return;

    const order = ORDER_LINE.exec(line);
    if (order) {
      const id = order[1]!;
      if (seen.has(id)) errors.push({ line: lineNo, description: `duplicate order id "${id}"` });
      seen.add(id);
      current = { id, line: lineNo, priority: order[2] !== undefined, items: [] };
      orders.push(current);
      return;
    }

    const item = ITEM_LINE.exec(line);
    if (item) {
      if (!current) {
        errors.push({ line: lineNo, description: "item line before the first ORDER line" });
        return;
      }
      const sku = item[1]!;
      const qty = Number(item[2]);
      const existing = (current as ParsedOrder).items.find((it) => it.sku === sku);
      if (existing) existing.qty += qty;
      else (current as ParsedOrder).items.push({ sku, qty });
      return;
    }

    errors.push({ line: lineNo, description: `unrecognized line "${line}"` });
  });

  for (const order of orders) {
    if (order.items.length === 0) {
      errors.push({ line: order.line, description: `order "${order.id}" has no items` });
    }
  }

  if (errors.length > 0) {
    const first = errors.reduce((a, b) => (b.line < a.line ? b : a));
    throw new OrderFormatError(first.line, first.description);
  }
  return orders;
}

function compareLots(a: StockLot, b: StockLot): number {
  if (a.expires !== b.expires) {
    if (a.expires === null) return 1;
    if (b.expires === null) return -1;
    return a.expires < b.expires ? -1 : 1;
  }
  if (a.bin !== b.bin) return a.bin < b.bin ? -1 : 1;
  return 0;
}

function parseBin(bin: string): { aisle: string; rack: number; level: number } {
  const [aisle = "", rack = "", level = ""] = bin.split("-");
  return { aisle, rack: Number(rack), level: Number(level) };
}

function compareStrings(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

export function buildPickList(ordersText: string, stock: StockLot[]): PickList {
  const orders = parseOrders(ordersText);
  const served = [...orders.filter((o) => o.priority), ...orders.filter((o) => !o.priority)];

  // Working copies so the caller's stock is never touched.
  const lotsBySku = new Map<string, { lot: StockLot; left: number }[]>();
  for (const lot of stock) {
    let list = lotsBySku.get(lot.sku);
    if (!list) lotsBySku.set(lot.sku, (list = []));
    list.push({ lot, left: lot.qty });
  }
  for (const list of lotsBySku.values()) list.sort((a, b) => compareLots(a.lot, b.lot));

  const picks: Pick[] = [];
  const shortages: Shortage[] = [];
  for (const order of served) {
    for (const item of order.items) {
      let needed = item.qty;
      for (const entry of lotsBySku.get(item.sku) ?? []) {
        if (needed === 0) break;
        if (entry.left <= 0) continue;
        const take = Math.min(needed, entry.left);
        entry.left -= take;
        needed -= take;
        picks.push({ bin: entry.lot.bin, sku: item.sku, qty: take, orderId: order.id });
      }
      if (needed > 0) shortages.push({ orderId: order.id, sku: item.sku, missing: needed });
    }
  }

  const aisles = [...new Set(picks.map((p) => parseBin(p.bin).aisle))].sort(compareStrings);
  const descending = new Set(aisles.filter((_, i) => i % 2 === 1));
  const keyed = picks.map((pick, index) => ({ pick, index, ...parseBin(pick.bin) }));
  keyed.sort((a, b) => {
    if (a.aisle !== b.aisle) return compareStrings(a.aisle, b.aisle);
    if (a.rack !== b.rack) return descending.has(a.aisle) ? b.rack - a.rack : a.rack - b.rack;
    if (a.level !== b.level) return a.level - b.level;
    return a.index - b.index;
  });

  return { picks: keyed.map((k) => k.pick), shortages };
}
'''
open(p,'w').write(s)
EOF

cat >> src/pickList.test.ts <<'EOF'

import { buildPickList, type StockLot } from "./pickList";

function errorLine(text: string): number | undefined {
  try {
    buildPickList(text, []);
  } catch (e) {
    expect(e).toBeInstanceOf(OrderFormatError);
    return (e as OrderFormatError).line;
  }
  return undefined;
}

test("example from the export", () => {
  const stock: StockLot[] = [
    { bin: "B-02-1", sku: "OLIVE-500", qty: 2, expires: null },
    { bin: "A-05-1", sku: "OLIVE-500", qty: 2, expires: "2026-11-01" },
    { bin: "A-01-3", sku: "OLIVE-500", qty: 2, expires: "2026-10-20" },
    { bin: "C-04-2", sku: "PASTA-1KG", qty: 5, expires: "2027-01-01" },
  ];
  const before = JSON.stringify(stock);
  const text = "# export\nORDER 1001\n  OLIVE-500 x3\n  PASTA-1KG x1\nORDER 1002 !\n  OLIVE-500 x2\n";
  const result = buildPickList(text, stock);
  expect(JSON.stringify(stock)).toBe(before);
  expect(result.picks).toEqual([
    { bin: "A-01-3", sku: "OLIVE-500", qty: 2, orderId: "1002" },
    { bin: "A-05-1", sku: "OLIVE-500", qty: 2, orderId: "1001" },
    { bin: "B-02-1", sku: "OLIVE-500", qty: 1, orderId: "1001" },
    { bin: "C-04-2", sku: "PASTA-1KG", qty: 1, orderId: "1001" },
  ]);
  expect(result.shortages).toEqual([]);
});

test("shortages, merged items and serpentine walk", () => {
  const stock: StockLot[] = [
    { bin: "B-01-1", sku: "X", qty: 1, expires: null },
    { bin: "B-09-2", sku: "Y", qty: 10, expires: null },
    { bin: "B-09-1", sku: "Z", qty: 10, expires: null },
    { bin: "D-01-1", sku: "W", qty: 10, expires: null },
    { bin: "D-03-1", sku: "V", qty: 10, expires: null },
  ];
  const text = "ORDER a\nX x2\nY x1\nX   x1\nZ x1\nW x1\nV x1\nQ x4";
  const result = buildPickList(text, stock);
  expect(result.picks.map((p) => p.bin)).toEqual(["B-01-1", "B-09-1", "B-09-2", "D-03-1", "D-01-1"].slice(0, 0).concat(
    ["B-01-1", "B-09-1", "B-09-2", "D-03-1", "D-01-1"],
  ).length ? ["B-01-1", "B-09-1", "B-09-2", "D-01-1", "D-03-1"] : []);
  expect(result.shortages).toEqual([
    { orderId: "a", sku: "X", missing: 2 },
    { orderId: "a", sku: "Q", missing: 4 },
  ]);
});

test("format errors", () => {
  expect(errorLine("\nX x1\nORDER 1\nX x1")).toBe(2);
  expect(errorLine("ORDER 1\nX x1\nORDER 1\nX x1")).toBe(3);
  expect(errorLine("ORDER 1\n# c\nORDER 2\nbad")).toBe(1);
  expect(errorLine("ORDER 1\nX x0")).toBe(2);
  expect(errorLine("ORDER 1\nX x03")).toBe(2);
  expect(errorLine("ORDER 1\nx x3")).toBe(2);
  expect(errorLine("ORDER 1\nX 3")).toBe(2);
  expect(errorLine("ORDER 1!\nX x3")).toBe(1);
  expect(errorLine("ORDER 1   !\nX x3")).toBeUndefined();
});
EOF
